// Some portions generated by Claude
package org.eclipse.rdf4j.workbench.base;

import static org.assertj.core.api.Assertions.assertThat;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

import javax.xml.parsers.DocumentBuilderFactory;

import org.junit.jupiter.api.Test;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;

/**
 * The Workbench front end (the classic TypeScript pages and the React graph explorer) is an npm project that Maven
 * builds on its own through the frontend-maven-plugin, so a plain {@code mvn package} produces a complete WAR without a
 * locally installed Node. The compiled output lives under {@code target/frontend} and is added to the WAR as a web
 * resource.
 */
class WorkbenchFrontendBuildTest {

	private static final String FRONTEND_PLUGIN = "frontend-maven-plugin";

	@Test
	void mavenRunsTheNpmBuildThroughTheFrontendPlugin() throws Exception {
		Element plugin = frontendPlugin();
		assertThat(plugin).as("frontend-maven-plugin declared in tools/workbench/pom.xml").isNotNull();

		List<String> goals = new ArrayList<>();
		List<String> npmArguments = new ArrayList<>();
		NodeList executions = plugin.getElementsByTagName("execution");
		for (int index = 0; index < executions.getLength(); index++) {
			Element execution = (Element) executions.item(index);
			goals.add(execution.getElementsByTagName("goal").item(0).getTextContent().trim());
			NodeList arguments = execution.getElementsByTagName("arguments");
			if (arguments.getLength() > 0) {
				npmArguments.add(arguments.item(0).getTextContent().trim());
			}
		}

		assertThat(goals).contains("install-node-and-npm", "npm");
		assertThat(npmArguments).anyMatch(arguments -> arguments.startsWith("ci"));
		assertThat(npmArguments).anyMatch(arguments -> arguments.equals("run build"));
	}

	@Test
	void theFrontendBuildCanBeSkippedForJavaOnlyWork() throws Exception {
		Element plugin = frontendPlugin();
		assertThat(plugin).isNotNull();

		NodeList executions = plugin.getElementsByTagName("execution");
		assertThat(executions.getLength()).isGreaterThan(0);
		for (int index = 0; index < executions.getLength(); index++) {
			Element execution = (Element) executions.item(index);
			NodeList skip = execution.getElementsByTagName("skip");
			assertThat(skip.getLength()).as("skip flag of execution " + index).isEqualTo(1);
			assertThat(skip.item(0).getTextContent().trim()).isIn("${skipFrontend}", "${skipFrontendInstall}");
		}
		// The install step has its own property so -DskipFrontend=true still skips everything (it defaults to
		// ${skipFrontend}); a warm checkout (node_modules present) runs npm install --no-save instead of npm ci.
		String pom = Files.readString(Path.of("pom.xml"));
		assertThat(pom).contains("<skipFrontendInstall>${skipFrontend}</skipFrontendInstall>");
		assertThat(pom).contains("<exists>${basedir}/node_modules</exists>");
	}

	/**
	 * A warm checkout must still follow a changed package-lock.json (skipping the install would build against stale
	 * packages), and must never rewrite the committed lockfile (a different npm version would reformat it).
	 */
	@Test
	void aWarmCheckoutSyncsNodeModulesWithoutRewritingTheLockfile() throws Exception {
		Document pom = pom();
		Element warm = null;
		NodeList profiles = pom.getElementsByTagName("profile");
		for (int index = 0; index < profiles.getLength(); index++) {
			Element profile = (Element) profiles.item(index);
			if ("frontend-installed".equals(childText(profile, "id"))) {
				warm = profile;
			}
		}
		assertThat(warm).as("profile frontend-installed").isNotNull();
		NodeList properties = warm.getElementsByTagName("skipFrontendInstall");
		assertThat(properties.getLength()).as("a warm checkout does not skip the install").isZero();

		String warmInstall = npmArguments(warm, "npm-ci");
		assertThat(warmInstall).as("warm install arguments").startsWith("install ").contains("--no-save");
		assertThat(warmInstall).doesNotContain("--package-lock=false");
		assertThat(npmArguments(frontendPlugin(), "npm-ci")).as("a cold checkout installs exactly the lockfile")
				.startsWith("ci ");
	}

	private static String npmArguments(Element scope, String executionId) {
		NodeList executions = scope.getElementsByTagName("execution");
		for (int index = 0; index < executions.getLength(); index++) {
			Element execution = (Element) executions.item(index);
			if (executionId.equals(childText(execution, "id"))) {
				return execution.getElementsByTagName("arguments").item(0).getTextContent().trim();
			}
		}
		throw new AssertionError("no execution " + executionId);
	}

	private static String childText(Element parent, String tag) {
		for (Node child = parent.getFirstChild(); child != null; child = child.getNextSibling()) {
			if (child instanceof Element element && tag.equals(element.getTagName())) {
				return element.getTextContent().trim();
			}
		}
		return null;
	}

	private static Document pom() throws Exception {
		DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
		factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
		return factory.newDocumentBuilder().parse(Path.of("pom.xml").toFile());
	}

	@Test
	void theWarPackagesTheBuiltFrontendAsWebResources() throws Exception {
		Element war = plugin("maven-war-plugin");
		assertThat(war).isNotNull();
		List<String> directories = new ArrayList<>();
		NodeList webResources = war.getElementsByTagName("webResources");
		for (int index = 0; index < webResources.getLength(); index++) {
			NodeList dirs = ((Element) webResources.item(index)).getElementsByTagName("directory");
			for (int dir = 0; dir < dirs.getLength(); dir++) {
				directories.add(dirs.item(dir).getTextContent().trim());
			}
		}
		assertThat(directories).contains("${project.build.directory}/frontend");
	}

	@Test
	void theNpmProjectBuildsBothFrontEnds() throws Exception {
		String packageJson = Files.readString(Path.of("package.json"));
		assertThat(packageJson).contains("\"build:classic\"").contains("\"build:explorer\"");
		assertThat(Files.exists(Path.of("package-lock.json"))).as("package-lock.json is committed").isTrue();
		assertThat(Files.exists(Path.of("tsconfig.classic.json"))).isTrue();
		assertThat(Files.exists(Path.of("vite.config.mts"))).isTrue();
	}

	private static Element frontendPlugin() throws Exception {
		return plugin(FRONTEND_PLUGIN);
	}

	private static Element plugin(String artifactId) throws Exception {
		DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
		factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
		Document pom = factory.newDocumentBuilder().parse(Path.of("pom.xml").toFile());
		NodeList plugins = pom.getElementsByTagName("plugin");
		for (int index = 0; index < plugins.getLength(); index++) {
			Element plugin = (Element) plugins.item(index);
			if (!"plugins".equals(plugin.getParentNode().getNodeName())) {
				continue;
			}
			Node build = plugin.getParentNode().getParentNode();
			if (build == null || !"build".equals(build.getNodeName())) {
				continue;
			}
			NodeList ids = plugin.getElementsByTagName("artifactId");
			if (ids.getLength() > 0 && artifactId.equals(ids.item(0).getTextContent().trim())) {
				return plugin;
			}
		}
		return null;
	}
}
